    enqueueCount = 0;

    const taskId = testUlid("TASK");
    const now = Date.now();
    const change: TaskStateChange = {
      taskId,
      taskRef: `@${taskId}`,
      fromStatus: "in_progress",
      toStatus: "pending",
      timestamp: now,
    };

    await engine.handleStateChange(change);
    expect(enqueueCount).toBe(1);

